--region public
---@param data table
---@param index integer
---@param isSelected boolean
---@param cb function 点击回调
function OverseaStoreSkinCommonCell:RefreshCell(storeType, data, index, isSelected, cb)
    self._cellData = data
    self._index = index
    self._cb = cb

    
    CfUtils.FillImage(self.ImgTag, CfUtils.GetImageFullPath(data.showImage))
    CfUtils.SetActive(self.StatusSelect, isSelected)
    
    -- 已拥有
    if storeType == OverseaStoreConstants.StoreType.SkinCard then
        CfUtils.SetActive(self.Finish, CardSkinComponent:IsHasSkin(data.icon))
    elseif storeType == OverseaStoreConstants.StoreType.SkinScene then
        local num = GoodsUtils.GetThingNo(data.icon)
        CfUtils.SetActive(self.Finish, num > 0)
    elseif storeType == OverseaStoreConstants.StoreType.SkinBundle then
        CfUtils.SetActive(self.Finish, CardSkinComponent:IsHasSkin(data.icon))
    else
        CfUtils.SetActive(self.Finish, false)
    end
    
    -- 互动标识
    if storeType == OverseaStoreConstants.StoreType.SkinCard or
        storeType == OverseaStoreConstants.StoreType.SkinBundle then
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(data.icon)
        CfUtils.SetActive(self.InteractiveGroup, IdolLive3D_Utils.GetLive3DCardVoRow(skinVo.skinId) and true or false)
    end

    if checkInt(data.iconId) == TagType.TimeLimit then
        -- 限时标签
        CfUtils.SetActive(self.TimeLimitGroup, checkInt(data.endTime) > 0)
        CfUtils.FillText(self.TxtTimeLimit, localize('限时'))
    elseif checkInt(data.iconId) == TagType.Discount then
        -- 折扣标签
        CfUtils.SetActive(self.TimeLimitGroup, true)
        CfUtils.FillText(self.TxtTimeLimit, localize('折扣'))
    else
        CfUtils.SetActive(self.TimeLimitGroup, false)
    end

end

function OverseaStoreSkinCommonCell:PlayAnimByHide()
    CfUtils.PlayAnimation(self.controller, 'UI_Common_List_Cell_Hide')
end


function OverseaStoreSkinCommonCell:PlayAnimByIdle()
    CfUtils.PlayAnimation(self.controller, 'UI_Common_List_Cell_Idle')
end


function OverseaStoreSkinCommonCell:PlayDelayAnimByShow(delayIndex)
    CfUtils.PlayDelayShowAnimation(self.controller, delayIndex, 'UI_Common_List_Cell_Show', 'UI_Common_List_Cell_Wait_3')
end
